// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public {
        c = new airdrop();
    }

    function testFuzz_property(address from, address to, uint256 amount) public {
        vm.assume(to != address(0));
        vm.assume(amount > 0);

        Recorder rec = new Recorder();
        address[] memory tos = new address[](1);
        tos[0] = to;

        bool ok;
        try c.transfer(from, address(rec), tos, amount) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        assertTrue(
            !ok ||
                (rec.callCount() > 0 &&
                    rec.selectorSeen() == bytes4(keccak256("transferFrom(address,address,uint256)")) &&
                    rec.lastFrom() == from &&
                    rec.lastTo() == to &&
                    rec.lastValue() == amount)
        );
    }
}

contract Recorder {
    uint256 public callCount;
    bytes4 public selectorSeen;
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        callCount++;
        selectorSeen = msg.sig;
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        callCount++;
        selectorSeen = msg.sig;
        return true;
    }
}
